import base64
import gzip
import hashlib
from pathlib import Path

path = Path('.chat-editor/e2e-recovery.patch.gz.b64')
encoded = ''.join(path.read_text().split())
assert hashlib.sha256(encoded.encode()).hexdigest() == '703baeadf44f97853a1ef6cfb044453d72e7d25cc898f240c38d1fcc126fd94a'
fragment = ''''''
assert len(fragment) == 4442
encoded = encoded[:5328] + fragment + encoded[5328:]
encoded = encoded[:1266] + 'f0' + encoded[1266:]
patch = gzip.decompress(base64.b64decode(encoded, validate=True))
assert hashlib.sha256(patch).hexdigest() == 'ce53a6f4d2034d674cb59aabd6c40cfda9797809a04be304239a689b8aa58525'
path.write_text(encoded + '\n')
print('Transport restored; original completed patch digest verified.')
